-- Topic: Misstatements and Control Deficiencies
-- Difficulty: 9E / 15M / 6H
-- Bloom's: L1:8 / L2:9 / L3:8 / L4:5

BEGIN;

INSERT INTO questions (section_id, topic, stem, choices, correct_index, explanation, difficulty, cognitive_level)
VALUES

-- Q1: medium / L2 — Clearly trivial misstatements threshold
(1, 'Misstatements and Control Deficiencies', 'During the audit of Greenfield Electronics Inc., the engagement partner sets overall materiality at $200,000 and performance materiality at $150,000. Under AU-C 450, the team designates misstatements below $10,000 as clearly trivial. This threshold means the auditor:', '["Must still accumulate and report all misstatements below $10,000 to management", "Should set the threshold at exactly 5% of overall materiality per auditing standards", "Is not required to accumulate misstatements below $10,000 because they are inconsequential by any criteria", "Must communicate all misstatements below $10,000 to those charged with governance"]'::jsonb, 2, 'Under AU-C 450.05, the auditor designates an amount below which misstatements are clearly trivial — meaning they would not need to be accumulated because they are inconsequential individually or in aggregate. This threshold is a matter of professional judgment and is not a fixed percentage. Choice B is incorrect because AU-C 450 does not prescribe a specific percentage; the clearly trivial threshold is determined based on the auditor''s judgment of the entity''s circumstances.', 'medium', 2),

-- Q2: easy / L1 — Definition of a misstatement per AU-C 450
(1, 'Misstatements and Control Deficiencies', 'Under AU-C 450, which of the following best defines a misstatement in the context of an audit?', '["An error in the financial statements caused exclusively by management fraud", "A difference between the amount, classification, presentation, or disclosure of a reported item and what is required under the applicable financial reporting framework", "A variance between budgeted and actual amounts reported in management discussion and analysis", "A computational error discovered during analytical procedures that exceeds performance materiality"]'::jsonb, 1, 'Under AU-C 450.04, a misstatement is defined as a difference between the amount, classification, presentation, or disclosure of a reported financial statement item and what is required under the applicable financial reporting framework. Misstatements may arise from error or fraud. Choice A is incorrect because misstatements encompass both errors and fraud, not exclusively fraud-related items.', 'easy', 1),

-- Q3: medium / L2 — Tolerable misstatement in sampling
(1, 'Misstatements and Control Deficiencies', 'Briarwood Manufacturing engages Morrison & Co. CPAs for its annual audit. The auditors use statistical sampling to test accounts receivable and set a tolerable misstatement of $45,000 for the account balance. Under AU-C 530, the tolerable misstatement in a sampling application represents:', '["The maximum misstatement in the population that the auditor is willing to accept and still conclude the sampling objective has been met", "The total of all misstatements found in the sample before the auditor must expand testing", "The amount below which individual misstatements are considered clearly trivial and need not be accumulated", "The aggregate misstatement threshold above which the auditor must issue a qualified opinion"]'::jsonb, 0, 'Under AU-C 530.05, tolerable misstatement is the application of performance materiality to a particular sampling procedure — it is the maximum misstatement in the population that the auditor can accept while still concluding the test objective is met. Choice C is incorrect because the clearly trivial threshold under AU-C 450 is a separate, much smaller amount used to screen individual misstatements, not to evaluate population-level sampling results.', 'medium', 2),

-- Q4: easy / L1 — Three categories of misstatements
(1, 'Misstatements and Control Deficiencies', 'Under auditing standards, what are the three categories of misstatements that an auditor should distinguish?', '["Material, immaterial, and pervasive misstatements", "Known, likely, and possible misstatements", "Intentional, unintentional, and systemic misstatements", "Factual, judgmental, and projected misstatements"]'::jsonb, 3, 'Under AU-C 450.A1, misstatements are classified into three categories: factual misstatements (about which there is no doubt), judgmental misstatements (arising from management''s judgments the auditor considers unreasonable), and projected misstatements (the auditor''s best estimate of population misstatements based on sample results). Choice B is incorrect because "known, likely, and possible" is outdated terminology not used in current clarified auditing standards.', 'easy', 1),

-- Q5: medium / L3 — Effect of fraud-related misstatement on control deficiency evaluation
(1, 'Misstatements and Control Deficiencies', 'During the audit of Sentinel Financial Group, the auditor discovers a $3,200 misstatement caused by intentional override of the invoice approval process by a mid-level manager. Overall materiality is $250,000. What is the most likely effect of this finding on the auditor''s evaluation of internal control?', '["The misstatement is immaterial and therefore has no effect on the auditor''s control evaluation", "The intentional nature of the override indicates at least a significant deficiency regardless of the dollar amount", "The deficiency should be classified based solely on the $3,200 amount relative to materiality", "The auditor should report this only to management since the amount is below performance materiality"]'::jsonb, 1, 'Under AU-C 265.A13, fraud of any magnitude by management or employees in positions of significant responsibility is an indicator of at least a significant deficiency and may constitute a material weakness. The intentional nature of the override, not just the dollar amount, drives the severity assessment. Choice C is incorrect because AU-C 265 requires the auditor to consider qualitative factors, including fraud and management override, beyond the purely quantitative impact of the misstatement.', 'medium', 3),

-- Q6: medium / L3 — Qualitative factors making a quantitatively immaterial misstatement material
(1, 'Misstatements and Control Deficiencies', 'Ridgeline Pharmaceuticals reports net income of $8.5 million. The auditor identifies an uncorrected $85,000 misstatement — well below the $400,000 materiality threshold — involving the improper classification of a related-party transaction. How should the auditor analyze whether this misstatement is material?', '["The misstatement is quantitatively immaterial and therefore does not require further analysis", "The auditor should project the misstatement to the entire population of related-party transactions", "The auditor should consider qualitative factors, such as the sensitivity of related-party disclosures, which may render the misstatement material despite its small dollar amount", "The auditor should request management correct the misstatement but cannot modify the opinion for an amount below materiality"]'::jsonb, 2, 'Under AU-C 450.A16, the auditor evaluates whether uncorrected misstatements are material individually or in aggregate by considering both quantitative and qualitative factors. Misstatements involving related-party transactions, regulatory compliance, or loan covenants may be qualitatively material regardless of size. Choice A is incorrect because a purely quantitative analysis is insufficient — AU-C 450 explicitly requires evaluation of qualitative circumstances surrounding the misstatement.', 'medium', 3),

-- Q7: medium / L2 — Reassessing strategy when misstatements accumulate
(1, 'Misstatements and Control Deficiencies', 'Cedar Valley Industries has overall materiality set at $150,000 and performance materiality at $112,500. Midway through the audit, Sterling & Associates CPAs have accumulated $95,000 in identified misstatements across several account balances, with significant testing still remaining. Under AU-C 450, the auditor should:', '["Issue a qualified opinion because accumulated misstatements exceed 50% of overall materiality", "Request management correct all identified misstatements before any additional testing", "Reduce the clearly trivial threshold to zero for all remaining audit procedures", "Consider whether the overall audit strategy and further audit procedures need to be revised given the level of accumulated misstatements"]'::jsonb, 3, 'Under AU-C 450.06, if the aggregate of misstatements accumulated during the audit approaches materiality, the auditor should consider whether the overall strategy needs revision. The accumulation of $95,000 against $150,000 materiality signals that additional misstatements from remaining work could cause the total to exceed materiality. Choice A is incorrect because there is no threshold at 50% that automatically triggers a qualified opinion; the auditor exercises professional judgment about strategy adjustments.', 'medium', 2),

-- Q8: medium / L3 — Evaluating management bias in uncorrected misstatements
(1, 'Misstatements and Control Deficiencies', 'Whitmore Holdings has eight uncorrected misstatements totaling $72,000, all of which increase reported net income. Overall materiality is $300,000. The auditor notices that no misstatements decrease income. What is the most likely implication of this pattern for the auditor''s evaluation?', '["The consistent direction of misstatements may indicate management bias, which the auditor should evaluate as a potential indicator of fraud risk", "Since each individual misstatement is immaterial, the directional pattern has no audit significance", "The auditor should offset these misstatements against any understatements found in other accounts", "The pattern indicates a systematic error in the accounting system rather than possible management bias"]'::jsonb, 0, 'Under AU-C 450.A15, the auditor should consider whether uncorrected misstatements share a common characteristic — such as consistently overstating income — that may indicate management bias. A pattern where all misstatements favor one direction may signal intentional bias and should be evaluated under AU-C 240 fraud considerations. Choice B is incorrect because AU-C 450 requires the auditor to evaluate qualitative patterns in uncorrected misstatements even when individual amounts are below materiality.', 'medium', 3),

-- Q9: easy / L1 — Timing of communicating control deficiencies
(1, 'Misstatements and Control Deficiencies', 'Under AU-C 265, when must the auditor communicate significant deficiencies and material weaknesses in writing to those charged with governance?', '["Immediately upon discovery during fieldwork", "Within 30 calendar days of the audit report date", "No later than 60 days following the report release date", "Before issuing the audit report so that governance can respond"]'::jsonb, 2, 'Under AU-C 265.13, the auditor must communicate significant deficiencies and material weaknesses in writing to those charged with governance no later than 60 days following the report release date. This allows time for the auditor to finalize the evaluation of identified deficiencies. Choice D is incorrect because while communication before the report date is encouraged, the standard permits written communication up to 60 days after the report release date.', 'easy', 1),

-- Q10: hard / L4 — Evaluating fraud-related misstatement and governance response
(1, 'Misstatements and Control Deficiencies', 'During the audit of Beacon Ridge Capital LLC, the auditor discovers that the CFO systematically altered journal entries to inflate revenue by $180,000 over two quarters. Overall materiality is $500,000. Management''s audit committee terminates the CFO and engages a forensic accountant. However, the board declines to restate the affected quarters, arguing the amounts are immaterial. The auditor should evaluate whether to:', '["Accept management''s position since the $180,000 misstatement is below overall materiality and the responsible individual has been terminated", "Consider the implications for the financial statements as a whole, including whether the uncorrected fraud misstatement and governance response affect the auditor''s ability to rely on management representations", "Automatically withdraw from the engagement because any fraud by senior management requires the auditor to resign", "Issue an adverse opinion solely because fraud was committed by a member of senior management"]'::jsonb, 1, 'Under AU-C 450.08 and AU-C 240.37, the auditor must evaluate the implications of identified fraud on the audit, including the reliability of management representations and the integrity of those charged with governance. The board''s refusal to correct a known fraud misstatement raises questions about management integrity even though the amount is below materiality. Choice C is incorrect because AU-C 240 does not mandate automatic withdrawal; rather, the auditor evaluates whether conditions exist that affect the ability to continue the engagement.', 'hard', 4),

-- Q11: easy / L1 — Definition of a control deficiency
(1, 'Misstatements and Control Deficiencies', 'Under AU-C 265, a control deficiency exists when:', '["The design or operation of a control does not allow management or employees to prevent, or detect and correct, misstatements on a timely basis", "The auditor identifies a misstatement that exceeds the clearly trivial threshold", "Management has not implemented all five components of the COSO framework", "The entity lacks a formal internal audit function to monitor financial reporting"]'::jsonb, 0, 'Under AU-C 265.07, a control deficiency exists when the design or operation of a control does not allow management or employees, in the normal course of performing their assigned functions, to prevent, or detect and correct, misstatements on a timely basis. Choice B is incorrect because identifying a misstatement above the clearly trivial threshold does not automatically mean a control deficiency exists — the misstatement must be linked to a specific control failure.', 'easy', 1),

-- Q12: easy / L1 — Management representation letter content on uncorrected misstatements
(1, 'Misstatements and Control Deficiencies', 'Under AU-C 580, management''s written representations regarding uncorrected misstatements should include:', '["A statement certifying that all financial statement balances are free from misstatement", "An assertion that no misstatements were identified during the audit engagement", "A pledge that all uncorrected misstatements will be corrected in the subsequent period", "An acknowledgment that the effects of uncorrected misstatements aggregated by the auditor are immaterial to the financial statements as a whole"]'::jsonb, 3, 'Under AU-C 580.A5, the auditor should request that management provide a written representation acknowledging that the effects of uncorrected misstatements aggregated during the audit are immaterial, both individually and in the aggregate, to the financial statements as a whole. A summary of these items is typically attached. Choice A is incorrect because the representations do not certify statements are free from misstatement — they acknowledge that uncorrected items are immaterial.', 'easy', 1),

-- Q13: medium / L2 — Fraud-caused immaterial misstatement and broader audit implications
(1, 'Misstatements and Control Deficiencies', 'Atlas Distribution Corp. reports total assets of $22 million. The auditor discovers that a warehouse manager created fictitious shipping records to conceal $8,500 in stolen inventory. Overall materiality is $440,000. Under AU-C 240, the auditor should:', '["Disregard the finding because the $8,500 amount is clearly trivial relative to overall materiality", "Record the misstatement in the summary of uncorrected differences but take no additional action", "Evaluate the implications of the fraud on the audit, including reconsidering the integrity of related management representations and the adequacy of controls over inventory", "Report the finding only to law enforcement since it involves employee theft"]'::jsonb, 2, 'Under AU-C 240.35-.36, when the auditor identifies a misstatement resulting from fraud, the auditor must consider the broader implications regardless of dollar amount. This includes reassessing the risk of material misstatement due to fraud, evaluating employee integrity, and determining whether additional audit procedures are necessary. Choice A is incorrect because AU-C 240 requires the auditor to evaluate any fraud finding for its broader implications, even when the misstatement itself is quantitatively immaterial.', 'medium', 2),

-- Q14: medium / L3 — Deficiency in design vs deficiency in operation
(1, 'Misstatements and Control Deficiencies', 'Pinnacle Aerospace Corp. has a documented policy requiring dual authorization for wire transfers exceeding $10,000. The auditor observes that the authorization form has only one signature field despite the two-signature policy. Separately, the auditor finds that a $25,000 wire transfer was approved by a single manager on a different form that has two signature lines. How should these findings be analyzed?', '["Both findings represent deficiencies in operation because the control was not performed as designed", "The single signature field is a deficiency in design and the single-manager approval on the two-line form is a deficiency in operation", "Both findings represent deficiencies in design because the dual authorization policy was not effectively implemented", "The single signature field is a deficiency in operation and the single-manager approval is a deficiency in design"]'::jsonb, 1, 'Under AU-C 265.A2, a design deficiency exists when a necessary control is missing or not properly designed to meet the control objective — here, the form lacking a second signature field. An operating deficiency exists when a properly designed control does not operate as intended — here, a two-line form was approved with only one signature. Choice A is incorrect because the single-field form issue is a design flaw that predates any operating failure.', 'medium', 3),

-- Q15: easy / L1 — Pervasive vs non-pervasive misstatement
(1, 'Misstatements and Control Deficiencies', 'In auditing, a misstatement is considered pervasive when it:', '["Is not confined to specific accounts and could affect a substantial proportion of the financial statements", "Exceeds the overall materiality threshold established for the audit by more than 50%", "Results from intentional fraud committed by a member of senior management", "Involves an undisclosed related-party transaction in the financial statement footnotes"]'::jsonb, 0, 'Under AU-C 705.06, pervasive effects on the financial statements are those that are not confined to specific elements, accounts, or items, or that represent a substantial proportion of the financial statements, or that are fundamental to users'' understanding. This concept determines whether a qualified or adverse opinion is appropriate. Choice B is incorrect because pervasiveness describes the breadth of the effect across the financial statements, not a specific quantitative threshold relative to materiality.', 'easy', 1),

-- Q16: easy / L2 — Accumulating identified misstatements during the audit
(1, 'Misstatements and Control Deficiencies', 'Blake & Torres CPAs identify four misstatements during the audit of Crescent Bay Hospitality: a $12,000 revenue overstatement, a $7,500 expense understatement, a $4,200 depreciation error, and a $1,800 classification error. Under AU-C 450, the auditor should:', '["Only accumulate the $12,000 and $7,500 misstatements since the others fall below performance materiality", "Report each misstatement separately to those charged with governance as it is discovered", "Accumulate only misstatements that individually exceed performance materiality", "Accumulate all identified misstatements during the audit, other than those that are clearly trivial"]'::jsonb, 3, 'Under AU-C 450.05, the auditor must accumulate all misstatements identified during the audit, other than those that are clearly trivial. All four misstatements should be accumulated regardless of individual size relative to performance materiality, as long as they exceed the clearly trivial threshold. Choice C is incorrect because the accumulation threshold is the clearly trivial amount, not performance materiality — all identified misstatements above clearly trivial must be included.', 'easy', 2),

-- Q17: medium / L3 — Effect of prior-year uncorrected misstatements on current year
(1, 'Misstatements and Control Deficiencies', 'During the prior-year audit of Harborview Logistics, $38,000 in uncorrected misstatements were noted. In the current year, the auditor determines these misstatements have a continuing effect on the current-year financial statements. Overall materiality for the current year is $175,000. What is the most likely effect of these prior-year misstatements on the current-year audit?', '["The auditor must include the $38,000 in the current-year summary of uncorrected misstatements when evaluating whether current-year statements are materially misstated", "Prior-year uncorrected misstatements are excluded from current-year evaluation because they were already considered in the prior audit", "The auditor should require management to correct the prior-year misstatements before beginning current-year fieldwork", "The prior-year misstatements only affect the current year if they resulted from fraud rather than error"]'::jsonb, 0, 'Under AU-C 450.07, the auditor must determine whether uncorrected misstatements from prior periods that have a continuing effect materially affect the current period''s financial statements. These amounts must be included in the aggregate evaluation of current-year misstatements. Choice B is incorrect because AU-C 450 explicitly requires prior-period uncorrected misstatements with continuing effects to be reconsidered in the current-year evaluation.', 'medium', 3),

-- Q18: medium / L2 — Requesting management to examine a class of transactions
(1, 'Misstatements and Control Deficiencies', 'While auditing Keystone Building Supply Inc., the auditor finds pricing errors in 6 of 40 sampled sales invoices. The errors total $14,000 in the sample, drawn from a population of 3,200 invoices. Management examines the broader population and corrects $52,000 in additional errors. Under AU-C 450, the auditor should:', '["Remove the original $14,000 sample errors from the summary since management corrected more than that amount", "Consider the remaining population error to be zero because management performed a complete review", "Evaluate whether management''s corrections adequately reduce the remaining projected misstatement for the population and determine if further procedures are needed", "Project the original $14,000 error rate to the full population without considering management''s corrections"]'::jsonb, 2, 'Under AU-C 450.08, when management examines a class of transactions and corrects misstatements found, the auditor must evaluate whether the corrections sufficiently address the projected misstatement. The auditor cannot simply assume all errors were found through management''s review. Choice B is incorrect because the auditor must exercise professional skepticism regarding the completeness of management''s review and may need to perform additional procedures to evaluate residual risk.', 'medium', 2),

-- Q19: medium / L2 — Corrected misstatements and internal control implications
(1, 'Misstatements and Control Deficiencies', 'During the audit of Redmond Supply Chain Corp., the auditor identifies 15 misstatements totaling $62,000, all of which management promptly corrects. The engagement partner asks whether these corrected misstatements have any further audit implications. Under auditing standards, the corrected misstatements:', '["Have no further audit implications once management has corrected them", "Should be evaluated for implications regarding internal control, including whether they indicate a pattern of control deficiencies requiring communication", "Must be reported as material weaknesses because the volume of errors indicates ineffective controls", "Should be included in the summary of uncorrected misstatements attached to the management representation letter"]'::jsonb, 1, 'Under AU-C 450.09 and AU-C 265.09, even when misstatements are corrected, the auditor should consider the nature and frequency of the errors for their implications on internal control. A pattern of 15 misstatements may indicate a control deficiency requiring communication. Choice A is incorrect because correction of misstatements does not eliminate the auditor''s responsibility to evaluate what those errors reveal about the design or operation of internal controls.', 'medium', 2),

-- Q20: hard / L4 — Evaluating adequacy of remediation plan for material weakness
(1, 'Misstatements and Control Deficiencies', 'During the audit of Northgate Financial Corp., the auditor identifies a material weakness in the loan loss reserve estimation process — management lacks qualified personnel to evaluate complex fair value inputs. The audit committee presents a remediation plan to hire two valuation analysts, but the positions will not be filled until four months after the fiscal year-end. The auditor should evaluate whether:', '["The remediation plan eliminates the material weakness because management has committed to corrective action", "The deficiency should be downgraded to a significant deficiency because the remediation plan demonstrates good faith", "The material weakness need not be communicated because management has an approved remediation plan", "The material weakness still exists as of the reporting date and must be communicated regardless of future remediation plans, since the condition existed during the period under audit"]'::jsonb, 3, 'Under AU-C 265.A18, the auditor evaluates control deficiencies as they existed during the audit period. A remediation plan that has not yet been implemented does not change the classification of a deficiency that existed during the period. The material weakness must be communicated in writing to those charged with governance. Choice A is incorrect because a commitment to future corrective action does not retroactively eliminate a deficiency present during the audit period.', 'hard', 4),

-- Q21: medium / L3 — Magnitude vs likelihood in evaluating control deficiency severity
(1, 'Misstatements and Control Deficiencies', 'Granite Peak Insurance processes 50,000 claims per year through an automated system. The auditor discovers that a validation check on claim amounts between $500 and $1,000 has been disabled for six months. Only 200 claims in this range were processed, and no misstatements were found in a sample. What factor most significantly affects the severity classification of this deficiency?', '["The magnitude of potential misstatement that could result before the deficiency would be detected by other controls, considering the volume of transactions affected", "The fact that no actual misstatements were identified in the sample, indicating the deficiency is immaterial", "The six-month duration of the disabled control, which automatically classifies the deficiency as a material weakness", "The $500 to $1,000 range of affected claims, which determines the maximum financial exposure"]'::jsonb, 0, 'Under AU-C 265.A7-.A8, severity of a control deficiency depends on both the magnitude of the potential misstatement and the likelihood of occurrence — the auditor considers what could result, not just what did result. The volume of transactions, compensating controls, and potential for undetected errors all factor into magnitude assessment. Choice B is incorrect because the absence of misstatements in a sample does not determine severity; AU-C 265 requires evaluation based on what reasonably could occur.', 'medium', 3),

-- Q22: medium / L2 — Form requirements of written communication
(1, 'Misstatements and Control Deficiencies', 'After completing the audit of Summit Creek Holdings, the auditor identifies two significant deficiencies and one material weakness. The audit committee chair requests the findings via email to expedite communication. Under AU-C 265, the written communication:', '["May only be delivered as a formal letter on the firm''s letterhead, not via email", "Must be in writing but is not restricted to a specific format, so an email meeting all content requirements of AU-C 265 would satisfy the standard", "Is required only for material weaknesses — significant deficiencies may be communicated orally", "Must be provided exclusively to the full board of directors, not to the audit committee"]'::jsonb, 1, 'Under AU-C 265.13, the auditor must communicate significant deficiencies and material weaknesses in writing to those charged with governance. The standard requires written communication but does not mandate a specific format such as a formal letter. An email that includes all required elements would satisfy the requirement. Choice C is incorrect because AU-C 265 requires written communication of both significant deficiencies and material weaknesses, not just material weaknesses.', 'medium', 2),

-- Q23: hard / L4 — Multi-location audit: aggregating deficiencies across components
(1, 'Misstatements and Control Deficiencies', 'Meridian Holdings Inc. operates through four subsidiaries, each audited by separate component auditors. The group engagement partner receives reports indicating each subsidiary has a control deficiency in its revenue recognition process — none individually classified as significant. However, revenue recognition uses the same enterprise system and shared controls across all subsidiaries. The group engagement partner should assess whether:', '["Each subsidiary''s deficiency should be evaluated independently since the component auditors already assessed severity", "The deficiencies can only be aggregated if total potential misstatement across subsidiaries exceeds group materiality", "The common system and shared controls indicate the deficiencies should be evaluated in combination, which may result in a significant deficiency or material weakness at the group level", "Group-level communication is unnecessary because each component auditor already communicated to subsidiary management"]'::jsonb, 2, 'Under AU-C 600.42 and AU-C 265.A11, the group engagement partner must evaluate control deficiencies identified at components in the context of the group audit. When deficiencies share a common root cause such as the same enterprise system, individual deficiencies that are not significant at the component level may constitute a significant deficiency or material weakness in combination at the group level. Choice A is incorrect because the group engagement partner has responsibility to evaluate the aggregate effect of component-level deficiencies on the group financial statements.', 'hard', 4),

-- Q24: hard / L3 — Distinguishing significant deficiency from material weakness with compensating controls
(1, 'Misstatements and Control Deficiencies', 'Heritage Manufacturing Corp. lacks segregation of duties in its accounts payable department — the same employee processes invoices, records payments, and reconciles vendor statements. However, the controller performs a detailed monthly review of all disbursements exceeding $5,000 and investigates discrepancies. The auditor tests the controller''s review and finds it consistently performed. How should the auditor classify this control environment?', '["The lack of segregation of duties is automatically a material weakness regardless of compensating controls", "The compensating control eliminates the deficiency entirely, so no communication is required", "The deficiency should be classified based on the volume of transactions below $5,000 that are not subject to the compensating review", "The lack of segregation of duties remains at least a significant deficiency, but the effective compensating control may prevent classification as a material weakness if it sufficiently reduces the likelihood of material misstatement"]'::jsonb, 3, 'Under AU-C 265.A10, compensating controls can mitigate the severity of a control deficiency. While lack of segregation of duties is inherently a deficiency, an effective compensating control such as detailed management review may reduce the likelihood that a material misstatement would occur undetected. However, the underlying deficiency still warrants communication as at least a significant deficiency. Choice A is incorrect because AU-C 265 requires the auditor to consider the totality of controls, including compensating controls, before classifying severity.', 'hard', 3),

-- Q25: hard / L4 — Reassessing risk when new misstatements found late in audit
(1, 'Misstatements and Control Deficiencies', 'Sterling Dynamics Inc. is nearing the completion of its December 31, 2025 audit. Overall materiality is $300,000. In the final week of fieldwork, the auditor discovers $185,000 in previously unidentified misstatements in inventory valuation. Previously accumulated uncorrected misstatements total $88,000 across other accounts. Management declines to adjust. The auditor should evaluate whether to:', '["Reconsider whether the assessed risks of material misstatement remain appropriate and determine if additional procedures are needed, given that aggregate uncorrected misstatements now approach materiality", "Accept the misstatements since neither the $185,000 nor the $88,000 individually exceeds the $300,000 materiality threshold", "Issue a disclaimer of opinion because the late discovery indicates the audit was insufficient", "Require management to correct only the $185,000 inventory misstatement and accept the remaining $88,000"]'::jsonb, 0, 'Under AU-C 450.06 and AU-C 315.31, when aggregate uncorrected misstatements ($273,000) approach materiality ($300,000), the auditor must reconsider the assessed risks and determine whether additional procedures are warranted. The late discovery of significant misstatements may indicate that prior risk assessments were insufficient. Choice B is incorrect because AU-C 450 requires evaluation of misstatements in aggregate, not individually; the combined $273,000 is close to the $300,000 materiality threshold.', 'hard', 4),

-- Q26: easy / L1 — Required management representation about misstatements
(1, 'Misstatements and Control Deficiencies', 'Under AU-C 580, what specific representation must the auditor obtain from management regarding misstatements?', '["A statement that no misstatements occurred during the fiscal year", "An acknowledgment that the effects of uncorrected misstatements are immaterial, both individually and in the aggregate, to the financial statements as a whole", "A commitment to correct all misstatements identified by the auditor within 90 days", "A certification that internal controls prevented all material misstatements from occurring"]'::jsonb, 1, 'Under AU-C 580.A5, the auditor obtains a written representation from management acknowledging that the effects of uncorrected misstatements are immaterial, individually and in aggregate, to the financial statements as a whole. A summary of uncorrected items is typically appended to the letter. Choice A is incorrect because the representation does not assert that no misstatements occurred — it specifically addresses the immateriality of known uncorrected misstatements.', 'easy', 1),

-- Q27: easy / L1 — Indicators that a control deficiency exists
(1, 'Misstatements and Control Deficiencies', 'Which of the following is an indicator that a control deficiency exists in an entity''s financial reporting process?', '["The entity uses a manual rather than automated accounting system", "The entity''s financial statements contain an immaterial rounding error", "A necessary control is missing or not designed to meet the relevant control objective", "The entity does not have a separate internal audit department"]'::jsonb, 2, 'Under AU-C 265.07, a control deficiency exists when a control necessary to prevent or detect and correct misstatements is missing or not suitably designed. The absence of a specific control needed to meet a control objective is a direct indicator of a design deficiency. Choice A is incorrect because using a manual accounting system does not itself constitute a control deficiency — manual systems can have adequate controls through compensating procedures such as management reviews.', 'easy', 1),

-- Q28: medium / L2 — Prior-period misstatement discovered in current period
(1, 'Misstatements and Control Deficiencies', 'During the 2026 audit of Birchwood Dental Group, the auditor discovers that $28,000 in equipment was erroneously expensed in 2025 rather than capitalized. The 2025 audit was performed by a predecessor auditor and the financial statements were not restated. Under AU-C 450, the current-year auditor should:', '["Ignore the prior-year error since it was the predecessor auditor''s responsibility", "Require restatement of the 2025 financial statements before completing the 2026 audit", "Treat the $28,000 as a current-year misstatement only if it was intentional", "Include the effect of the prior-period misstatement in the current-year evaluation of uncorrected misstatements to the extent it affects the current-year financial statements"]'::jsonb, 3, 'Under AU-C 450.07, when the auditor identifies a prior-period misstatement that affects current-period financial statements — here, through understated assets and incorrect depreciation expense — the effect must be included in the current-year evaluation. The misstatement has a continuing effect on the 2026 balance sheet. Choice A is incorrect because the current auditor has responsibility to evaluate misstatements affecting the current period regardless of which auditor performed the prior-year engagement.', 'medium', 2),

-- Q29: hard / L4 — Evaluating net effect of offsetting misstatements
(1, 'Misstatements and Control Deficiencies', 'During the audit of Pacific Crest Energy Corp., the auditor identifies two uncorrected misstatements: a $120,000 overstatement of accounts receivable and a $115,000 understatement of accrued liabilities. Management argues the net effect on the balance sheet is only $5,000 and therefore immaterial. Overall materiality is $250,000. The auditor should evaluate whether:', '["Management''s netting approach is acceptable because the net balance sheet effect is clearly immaterial at $5,000", "The misstatements should not be offset because they affect different financial statement line items and each misstatement individually affects the fair presentation of those accounts", "The misstatements should be netted only if they relate to the same transaction cycle", "The overstatement and understatement cancel out for purposes of the aggregate evaluation, reducing total uncorrected misstatements to $5,000"]'::jsonb, 1, 'Under AU-C 450.A14, the auditor should not offset misstatements in different accounts even when the net effect on a subtotal appears minimal. Each misstatement affects the fair presentation of the specific account in which it occurs. A $120,000 overstatement of receivables misstates the current asset position regardless of any unrelated liability understatement. Choice A is incorrect because AU-C 450 does not permit netting misstatements across different line items; each must be evaluated for its effect on the financial statement elements it directly affects.', 'hard', 4),

-- Q30: medium / L3 — Impact of IT general control deficiency on dependent application controls
(1, 'Misstatements and Control Deficiencies', 'Vista Technology Group relies on an automated three-way matching control in its ERP system to approve vendor payments. The auditor discovers that the IT department did not restrict access to the program change management module, allowing developers to modify production code without approval. No unauthorized changes were detected. How should the IT access deficiency affect the auditor''s evaluation of the three-way matching control?', '["The three-way matching control can still be relied upon because no unauthorized code changes were detected", "The IT access deficiency only affects IT controls and has no bearing on the application-level matching control", "The auditor should evaluate whether the IT general control deficiency undermines the reliability of the automated three-way matching control, since the application control depends on the integrity of the underlying system", "The auditor should classify the three-way matching control as a material weakness based solely on the IT access deficiency"]'::jsonb, 2, 'Under AU-C 315.A69 and AU-C 265.A6, IT general controls support the continued proper functioning of application controls. When an IT general control such as program change management is deficient, the auditor must consider whether dependent application controls can still be relied upon, because unauthorized changes could compromise automated control logic. Choice A is incorrect because the absence of detected changes does not ensure the application control operated as designed throughout the period.', 'medium', 3)
;

COMMIT;
